import * as React from "react";
import { ResponsiveContainer, AreaChart, Area, BarChart, Bar, LineChart, Line, Tooltip } from "recharts";
import { clsx } from "clsx";
const AnalyticsCard = React.forwardRef(({ className, title, value, trend, trendType = "neutral", // "positive" | "negative" | "neutral"
description, chartData = [], // Array of { value: 10, label: "..." }
chartType = "area", // "area" | "bar" | "line"
chartColor = "var(--primary)", ...props }, ref) => {
    const isPositive = trendType === "positive";
    const isNegative = trendType === "negative";
    const renderChart = () => {
        if (!chartData || chartData.length === 0)
            return null;
        if (chartType === "bar") {
            return (<ResponsiveContainer width="100%" height="100%">
          <BarChart data={chartData}>
            <Tooltip content={({ active, payload }) => {
                    if (active && payload && payload.length) {
                        return (<div className="rounded-lg border border-[var(--border)] bg-[var(--popover)] p-1.5 shadow-md text-[10px] font-bold text-[var(--foreground)]">
                      {payload[0].value}
                    </div>);
                    }
                    return null;
                }}/>
            <Bar dataKey="value" fill={chartColor} radius={[4, 4, 0, 0]}/>
          </BarChart>
        </ResponsiveContainer>);
        }
        if (chartType === "line") {
            return (<ResponsiveContainer width="100%" height="100%">
          <LineChart data={chartData}>
            <Tooltip content={({ active, payload }) => {
                    if (active && payload && payload.length) {
                        return (<div className="rounded-lg border border-[var(--border)] bg-[var(--popover)] p-1.5 shadow-md text-[10px] font-bold text-[var(--foreground)]">
                      {payload[0].value}
                    </div>);
                    }
                    return null;
                }}/>
            <Line type="monotone" dataKey="value" stroke={chartColor} strokeWidth={2} dot={false} activeDot={{ r: 4 }}/>
          </LineChart>
        </ResponsiveContainer>);
        }
        // Default "area" chart
        return (<ResponsiveContainer width="100%" height="100%">
        <AreaChart data={chartData}>
          <defs>
            <linearGradient id="gradientColor" x1="0" y1="0" x2="0" y2="1">
              <stop offset="5%" stopColor={chartColor} stopOpacity={0.25}/>
              <stop offset="95%" stopColor={chartColor} stopOpacity={0.0}/>
