          <Tooltip content={({ active, payload }) => {
                if (active && payload && payload.length) {
                    return (<div className="rounded-lg border border-[var(--border)] bg-[var(--popover)] p-1.5 shadow-md text-[10px] font-bold text-[var(--foreground)]">
                    {payload[0].value}
                  </div>);
                }
                return null;
            }}/>
          <Area type="monotone" dataKey="value" stroke={chartColor} strokeWidth={2} fillOpacity={1} fill="url(#gradientColor)"/>
        </AreaChart>
      </ResponsiveContainer>);
    };
    return (<div ref={ref} className={clsx("rounded-2xl border border-[var(--border)] bg-[var(--popover)] p-5 shadow-sm hover:shadow-md transition-shadow flex flex-col justify-between h-[180px] w-full text-left overflow-hidden", className)} style={{
            backgroundColor: "var(--popover-bg, var(--bg-surface, #ffffff))",
            borderColor: "var(--border)",
            color: "var(--foreground)"
        }} {...props}>
      <div>
        <div className="flex items-center justify-between gap-4">
          <span className="text-xs font-bold uppercase tracking-wider text-slate-400 select-none">
            {title}
          </span>
          {trend && (<span className={clsx("inline-flex items-center gap-0.5 rounded-full px-2 py-0.5 text-[10px] font-bold uppercase select-none", isPositive && "bg-emerald-500/10 text-emerald-600 dark:text-emerald-400", isNegative && "bg-red-500/10 text-red-600 dark:text-red-400", !isPositive && !isNegative && "bg-slate-100 text-slate-600 dark:bg-slate-800 dark:text-slate-400")}>
