Autocomplete:
import * as React from "react";
import { motion, AnimatePresence } from "framer-motion";
const clsx = (...classes) => classes.filter(Boolean).join(" ");
const Autocomplete = React.forwardRef(({ className, options = [], value = "", onValueChange, defaultValue = "", placeholder = "Search items...", disabled = false, label, id, ...props }, ref) => {
    const [inputValue, setInputValue] = React.useState(value !== undefined ? value : defaultValue);
    const [open, setOpen] = React.useState(false);
    const [activeSuggestion, setActiveSuggestion] = React.useState(0);
    const containerRef = React.useRef(null);
    const inputRef = React.useRef(null);
    const generatedId = React.useId();
    const inputId = id || generatedId;
    React.useEffect(() => {
        if (value !== undefined) {
            setInputValue(value);
        }
    }, [value]);
    const updateValue = (val) => {
        if (disabled)
            return;
        if (value === undefined) {
            setInputValue(val);
        }
        if (onValueChange) {
            onValueChange(val);
        }
    };
    const filteredOptions = React.useMemo(() => {
        if (!inputValue)
            return options;
        return options.filter(option => option.label.toLowerCase().includes(inputValue.toLowerCase()));
    }, [options, inputValue]);
    // Click outside listener to collapse
    React.useEffect(() => {
        const handleClickOutside = (e) => {
            if (containerRef.current && !containerRef.current.contains(e.target)) {
                setOpen(false);
            }
        };
        document.addEventListener("mousedown", handleClickOutside);
        return () => document.removeEventListener("mousedown", handleClickOutside);
    }, []);
    const handleSelectOption = (option) => {
        updateValue(option.label);
        setOpen(false);
        setActiveSuggestion(0);
    };
    const handleClear = (e) => {
        e.stopPropagation();
        updateValue("");
        setOpen(true);
        inputRef.current?.focus();
    };
    const handleKeyDown = (e) => {
        if (disabled)
            return;
        if (e.key === "ArrowDown") {
            e.preventDefault();
            if (!open) {
                setOpen(true);
                return;
            }
            setActiveSuggestion(prev => prev + 1 >= filteredOptions.length ? 0 : prev + 1);
        }
        else if (e.key === "ArrowUp") {
            e.preventDefault();
            if (!open)
                return;
            setActiveSuggestion(prev => prev - 1 < 0 ? filteredOptions.length - 1 : prev - 1);
        }
        else if (e.key === "Enter") {
            if (open && filteredOptions[activeSuggestion]) {
                e.preventDefault();
                handleSelectOption(filteredOptions[activeSuggestion]);
            }
        }
        else if (e.key === "Escape") {
            setOpen(false);
            inputRef.current?.blur();
        }
