      <div className="flex flex-col sm:flex-row sm:items-center sm:justify-between gap-4">
        {searchKey && (<div className="w-full sm:max-w-xs">
            <Input placeholder={placeholder} value={searchTerm} onChange={(e) => setSearchTerm(e.target.value)} className="h-10 text-xs bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-800"/>
          </div>)}
        <div className="flex items-center gap-2">
          <span className="text-xs font-semibold text-slate-500 dark:text-slate-400">
            Showing {paginatedData.length} of {sortedData.length} entries
          </span>
        </div>
      </div>

      {/* Table Container */}
      <div className="rounded-xl border border-slate-200 dark:border-slate-800 overflow-hidden shadow-sm bg-white dark:bg-slate-900">
        <div className="w-full overflow-x-auto">
