import * as React from "react";
const clsx = (...classes) => classes.filter(Boolean).join(" ");
const FileUpload = React.forwardRef(({ className, onFileSelect, accept, maxSize, // in MB
multiple = false, label = "Upload file", description = "Drag & drop files here, or click to browse", ...props }, ref) => {
    const [isDragOver, setIsDragOver] = React.useState(false);
    const [selectedFiles, setSelectedFiles] = React.useState([]);
    const [uploadProgress, setUploadProgress] = React.useState(0);
    const [isUploading, setIsUploading] = React.useState(false);
    const inputRef = React.useRef(null);
    const handleDragOver = (e) => {
        e.preventDefault();
        setIsDragOver(true);
    };
    const handleDragLeave = () => {
        setIsDragOver(false);
    };
    const handleDrop = (e) => {
        e.preventDefault();
        setIsDragOver(false);
        if (e.dataTransfer.files) {
            const files = Array.from(e.dataTransfer.files);
            processFiles(files);
        }
    };
    const handleFileChange = (e) => {
        if (e.target.files) {
            const files = Array.from(e.target.files);
            processFiles(files);
        }
    };
    const processFiles = (files) => {
        // Validation
        const validFiles = files.filter((file) => {
            if (maxSize && file.size > maxSize * 1024 * 1024) {
                alert(`File ${file.name} exceeds the maximum size of ${maxSize}MB.`);
                return false;
            }
            return true;
        });
        if (validFiles.length === 0)
            return;
        setSelectedFiles(multiple ? [...selectedFiles, ...validFiles] : [validFiles[0]]);
        onFileSelect?.(multiple ? validFiles : validFiles[0]);
        // Simulate progress animation
        setIsUploading(true);
        setUploadProgress(0);
        const interval = setInterval(() => {
            setUploadProgress(prev => {
                if (prev >= 100) {
                    clearInterval(interval);
                    setIsUploading(false);
                    return 100;
                }
                return prev + 10;
            });
        }, 150);
    };
    const triggerSelect = () => {
        inputRef.current?.click();
    };
    const removeFile = (index) => {
        const nextFiles = [...selectedFiles];
        nextFiles.splice(index, 1);
        setSelectedFiles(nextFiles);
