import * as React from "react";
import { motion, AnimatePresence } from "framer-motion";
const clsx = (...classes) => classes.filter(Boolean).join(" ");
const MultiSelect = React.forwardRef(({ className, options = [], value = [], onValueChange, defaultValue = [], placeholder = "Select options...", disabled = false, maxSelected = null, ...props }, ref) => {
    const [selected, setSelected] = React.useState(value !== undefined ? value : defaultValue);
    const [open, setOpen] = React.useState(false);
    const [search, setSearch] = React.useState("");
    const containerRef = React.useRef(null);
    const inputRef = React.useRef(null);
    React.useImperativeHandle(ref, () => containerRef.current);
    React.useEffect(() => {
        if (value !== undefined) {
            setSelected(value);
        }
    }, [value]);
    const updateSelected = (newSelected) => {
        if (disabled)
            return;
        if (value === undefined) {
            setSelected(newSelected);
        }
        if (onValueChange) {
            onValueChange(newSelected);
        }
    };
    const handleSelectOption = (optionValue) => {
        if (selected.includes(optionValue)) {
            updateSelected(selected.filter(item => item !== optionValue));
        }
        else {
            if (maxSelected && selected.length >= maxSelected)
                return;
            updateSelected([...selected, optionValue]);
        }
        setSearch("");
        inputRef.current?.focus();
    };
    const handleRemoveOption = (optionValue, e) => {
        e.stopPropagation();
        if (disabled)
            return;
        updateSelected(selected.filter(item => item !== optionValue));
    };
    const handleClearAll = (e) => {
        e.stopPropagation();
        if (disabled)
            return;
        updateSelected([]);
        setSearch("");
        setOpen(false);
    };
    const handleKeyDown = (e) => {
        if (disabled)
            return;
        if (e.key === "Backspace" && search === "" && selected.length > 0) {
            updateSelected(selected.slice(0, -1));
        }
        if (e.key === "Escape") {
            setOpen(false);
            inputRef.current?.blur();
        }
        if (e.key === "ArrowDown" && !open) {
            e.preventDefault();
            setOpen(true);
        }
    };
    // Close when clicking outside
    React.useEffect(() => {
        const handleClickOutside = (e) => {
            if (containerRef.current && !containerRef.current.contains(e.target)) {
                setOpen(false);
            }
        };
        document.addEventListener("mousedown", handleClickOutside);
        return () => document.removeEventListener("mousedown", handleClickOutside);
    }, []);
    const filteredOptions = options.filter(option => option.label.toLowerCase().includes(search.toLowerCase()));
    return (<div ref={containerRef} className={clsx("relative w-full", className)} onKeyDown={handleKeyDown} {...props}>
      {/* Control Box */}
      <div onClick={() => !disabled && setOpen(!open)} className={clsx("flex min-h-[44px] w-full flex-wrap items-center justify-between rounded-xl border border-[var(--border)] bg-transparent px-3 py-1 text-sm transition-all focus-within:ring-4 focus-within:ring-[var(--ring)]/20 cursor-pointer", disabled && "opacity-50 cursor-not-allowed", open ? "border-[var(--primary)]" : "hover:border-[var(--border)]")}>
        <div className="flex flex-wrap gap-1.5 items-center flex-1">
          {selected.map(itemVal => {
            const opt = options.find(o => o.value === itemVal);
            const label = opt ? opt.label : itemVal;
            return (<span key={itemVal} className="inline-flex items-center gap-1 rounded-lg bg-[var(--primary)]/10 text-[var(--primary)] px-2 py-0.5 text-xs font-semibold">
                {label}
                <button type="button" disabled={disabled} onClick={(e) => handleRemoveOption(itemVal, e)} className="rounded-full hover:bg-[var(--primary)]/20 p-0.5 transition-colors focus:outline-none">
                  <svg className="h-3 w-3" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5">
                    <line x1="18" y1="6" x2="6" y2="18"></line>
                    <line x1="6" y1="6" x2="18" y2="18"></line>
                  </svg>
                </button>
              </span>);
        })}

          <input ref={inputRef} type="text" disabled={disabled} value={search} onChange={(e) => {
            setSearch(e.target.value);
            setOpen(true);
        }} placeholder={selected.length === 0 ? placeholder : ""} className="flex-1 min-w-[60px] bg-transparent py-1 font-medium text-[var(--foreground)] placeholder:text-slate-400 outline-none border-none focus:ring-0 text-xs"/>
        </div>

        <div className="flex items-center gap-1.5 shrink-0 ml-2">
          {selected.length > 0 && !disabled && (<button type="button" onClick={handleClearAll} className="p-1 rounded-md text-slate-400 hover:text-slate-600 hover:bg-slate-100 dark:hover:bg-slate-800 transition-colors">
              <svg className="h-3.5 w-3.5" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5">
                <line x1="18" y1="6" x2="6" y2="18"></line>
                <line x1="6" y1="6" x2="18" y2="18"></line>
              </svg>
            </button>)}
          <span className="text-slate-400">
            <svg className={clsx("h-4 w-4 transition-transform duration-200", open && "rotate-180")} viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2">
              <polyline points="6 9 12 15 18 9"/>
