    const [isOpen, setIsOpen] = React.useState(false);
    const directions = {
        top: { initial: { y: 6, x: "-50%" }, animate: { y: 0, x: "-50%" } },
        bottom: { initial: { y: -6, x: "-50%" }, animate: { y: 0, x: "-50%" } },
        left: { initial: { x: 6, y: "-50%" }, animate: { x: 0, y: "-50%" } },
